// Pull the members array out of Mailchimp's response, return as one item.
const body = $input.first().json;
const members = body.members || [];
return [{ json: { members } }];

// Filter sessions to the target event AND only those actually on sale.
// Also derive a smart event name that handles Onebox placeholder titles.
const eventId = Number($('Vars').first().json.event_id);
const resp = $input.first().json;
const sessions = resp.data ?? [];

function isPlaceholder(s) {
  if (!s) return true;
  const x = s.trim();
  return (x.startsWith('*')
          || /\bAPI\b/i.test(x)
          || ['NUMERADO','EVENT','TEST','DEMO'].includes(x.toUpperCase()));
}

function smartTitle(s) {
  const candidates = [s.event && s.event.name, s.name];
  const real = candidates.find(c => c && !isPlaceholder(c));
  if (real) return real;
  const venue = s.venue && s.venue.name;
  const dateStr = s.date && s.date.start
    ? new Date(s.date.start).toLocaleDateString('es-ES', { day: 'numeric', month: 'short', year: 'numeric' })
    : '';
  if (venue && dateStr) return 'Partido en ' + venue + ' — ' + dateStr;
  if (venue) return 'Partido en ' + venue;
  return 'Próximo partido';
}

return sessions
  .filter(s => Number(s.event && s.event.id) === eventId)
  .filter(s => s.on_sale === true && s.sold_out !== true)
  .map(s => ({
    json: {
      session_id:   s.id,
      session_name: s.name,
      event_id:     s.event && s.event.id,
      event_name:   smartTitle(s),
      venue:        (s.venue && s.venue.name) || null,
      date:         (s.date && s.date.start) || null,
      on_sale:      !!s.on_sale,
      sold_out:     !!s.sold_out
    }
  }));

// Emit one item per (session, sector) that has available seats.
const sessions = $('Filter by event_id').all();
const responses = $input.all();

const out = [];
for (let i = 0; i < responses.length; i++) {
  const avail = responses[i].json;
  const sess  = (sessions[i] && sessions[i].json) || {};
  const sessionId = avail.id || sess.session_id;

  for (const sec of avail.sectors || []) {
    let available = 0, total = 0;
    for (const pt of sec.price_types || []) {
      available += (pt.availability && pt.availability.available) || 0;
      total     += (pt.availability && pt.availability.total) || 0;
    }
    if (available > 0) {
      out.push({ json: {
        event_id:   sess.event_id,
        session_id: sessionId,
        event_name: sess.event_name,
        venue:      sess.venue,
        date:       sess.date,
        grada_id:   sec.id,
        grada_name: sec.name,
        grada_code: sec.code || null,
        available,
        total
      }});
    }
  }
}
return out;

// For each grada with availability, find subscribers tagged with
// event:<id>, grada:<id>, source:avisame, AND NOT yet tagged
// notified:<event>:<grada>. Returns one item per (subscriber, grada).
const members = ($('Aggregate members').first().json.members) || [];
const gradas  = $input.all();
const purchaseTpl = ($('Vars').first().json.purchase_url_template) || '';
const wantSource = 'source:avisame';

const out = [];
for (const g of gradas) {
  const ctx = g.json;
  const wantEvent   = 'event:' + ctx.event_id;
  const wantGrada   = 'grada:' + ctx.grada_id;
  const notifiedTag = 'notified:' + ctx.event_id + ':' + ctx.grada_id;

  for (const m of members) {
    if (m.status !== 'subscribed') continue;
    const tagNames = ((m.tags) || []).map(t => t.name);
    if (!tagNames.includes(wantEvent))    continue;
    if (!tagNames.includes(wantGrada))    continue;
    if (!tagNames.includes(wantSource))   continue;
    if (tagNames.includes(notifiedTag))   continue;  // dedup

    out.push({ json: {
      email:           m.email_address,
      subscriber_hash: m.id,
      first_name:      (m.merge_fields && m.merge_fields.FNAME) || '',
      last_name:       (m.merge_fields && m.merge_fields.LNAME) || '',
      event_id:        ctx.event_id,
      event_name:      ctx.event_name,
      session_id:      ctx.session_id,
      grada_id:        ctx.grada_id,
      grada_name:      ctx.grada_name,
      available:       ctx.available,
      notified_tag:    notifiedTag,
      purchase_url: purchaseTpl
        .replace('{sessionId}', String(ctx.session_id))
        .replace('{eventId}',   String(ctx.event_id))
        .replace('{gradaId}',   String(ctx.grada_id))
    }});
  }
}
return out;

// Build subject + branded HTML body + Mandrill payload for each lead.
const siteUrl    = ($('Vars').first().json.site_url) || '';
const unsubEmail = ($('Vars').first().json.unsubscribe_email) || 'privacidad@rccelta.es';
const fromEmail  = ($('Vars').first().json.mandrill_from_email);
const fromName   = ($('Vars').first().json.mandrill_from_name);

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const greeting = d.first_name ? '¡Hola ' + d.first_name + ', ya están a la venta!' : '¡Ya están a la venta!';
  const subject  = '🎟️ ¡Entradas en ' + d.grada_name + ' para ' + d.event_name + '!';
  const unsubMail = 'mailto:' + unsubEmail
    + '?subject=' + encodeURIComponent('Baja de suscripción')
    + '&body='    + encodeURIComponent('Por favor, da de baja la suscripción del correo ' + d.email);

  const html =
    '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>¡Entradas disponibles! — RC Celta</title></head>'
  + '<body style="margin:0; padding:0; background:#f4f6f9; font-family:Arial, sans-serif; color:#1a2a3a;">'
  + '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f6f9;"><tr><td align="center" style="padding:32px 16px;">'
  + '<table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px; background:#ffffff; border-radius:12px;">'
  + '<tr><td align="center" style="background:#0d1b2a; padding:28px 24px; border-radius:12px 12px 0 0;">'
  +   '<div style="color:#ffffff; font-size:22px; font-weight:bold; letter-spacing:0.5px;">RC CELTA DE VIGO</div>'
  +   '<div style="padding-top:6px; color:#6cace4; font-size:11px; font-weight:bold; letter-spacing:2px; text-transform:uppercase;">Aviso de entradas</div>'
  + '</td></tr>'
  + '<tr><td align="center" style="background:#d50032; color:#ffffff; padding:14px 24px; font-size:14px; font-weight:bold; letter-spacing:2px; text-transform:uppercase;">🎟️ ¡Entradas disponibles!</td></tr>'
  + '<tr><td style="padding:36px 40px 8px 40px;">'
  +   '<h1 style="margin:0 0 14px 0; font-size:28px; line-height:1.2; font-weight:bold; color:#1a2a3a;">' + greeting + '</h1>'
  +   '<p style="margin:0 0 24px 0; font-size:16px; line-height:1.6; color:#4a5e70;">Hay entradas disponibles en tu grada favorita. Date prisa, vuelan rápido.</p>'
  + '</td></tr>'
  + '<tr><td style="padding:0 40px 28px 40px;">'
  +   '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f6f9; border-radius:10px; border-left:4px solid #6cace4;"><tr><td style="padding:20px 22px;">'
  +     '<div style="font-size:11px; font-weight:bold; letter-spacing:2px; text-transform:uppercase; color:#8fa3b8; margin-bottom:4px;">Tu partido</div>'
  +     '<div style="font-size:20px; font-weight:bold; color:#1a2a3a; margin-bottom:14px;">' + d.event_name + '</div>'
  +     '<div style="font-size:11px; font-weight:bold; letter-spacing:1.5px; text-transform:uppercase; color:#8fa3b8; margin-bottom:3px;">Grada</div>'
  +     '<div style="font-size:15px; font-weight:600; color:#1a2a3a; margin-bottom:14px;">' + d.grada_name + '</div>'
  +     '<div style="font-size:11px; font-weight:bold; letter-spacing:1.5px; text-transform:uppercase; color:#8fa3b8; margin-bottom:3px;">Disponibilidad</div>'
  +     '<div style="font-size:15px; font-weight:600; color:#2ea043;">' + d.available + ' localidades</div>'
  +   '</td></tr></table>'
  + '</td></tr>'
  + '<tr><td align="center" style="padding:0 40px 12px 40px;">'
  +   '<a href="' + d.purchase_url + '" style="display:inline-block; padding:18px 48px; font-size:16px; font-weight:bold; letter-spacing:2px; color:#ffffff; text-decoration:none; background:#d50032; border-radius:10px;">COMPRAR ENTRADAS</a>'
  + '</td></tr>'
  + '<tr><td align="center" style="padding:0 40px 32px 40px; font-size:13px; line-height:1.55; color:#8fa3b8;">⏰ Las entradas se agotan rápido. Recomendamos comprarlas hoy mismo.</td></tr>'
  + '<tr><td style="padding:0 40px;"><div style="border-top:1px solid #e4eaf1; height:1px; line-height:1px; font-size:0;">&nbsp;</div></td></tr>'
  + '<tr><td style="padding:24px 40px 40px 40px;">'
  +   '<p style="margin:0 0 10px 0; font-size:14px; line-height:1.6; color:#4a5e70;">Recibes este aviso porque te suscribiste al servicio <strong>¡Avísame!</strong> del RC Celta de Vigo para esta grada y este partido.</p>'
  +   '<p style="margin:0; font-size:14px; line-height:1.6; color:#4a5e70;">¡Nos vemos en Balaídos! 💙</p>'
  + '</td></tr></table>'
  + '<table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;">'
  + '<tr><td align="center" style="padding:24px 16px 0 16px; font-size:12px; line-height:1.55; color:#8fa3b8;">'
  +   '<p style="margin:0 0 6px 0;">Real Club Celta de Vigo, S.A.D. — CIF A-36603587<br>Estadio de Balaídos, Avenida de Balaídos s/n, 36210 Vigo (Pontevedra), España</p>'
  +   '<p style="margin:14px 0 0 0;">'
  +     '<a href="' + siteUrl + '/aviso-legal.html" style="color:#8fa3b8;">Aviso Legal</a> · '
  +     '<a href="' + siteUrl + '/privacidad.html" style="color:#8fa3b8;">Privacidad</a> · '
  +     '<a href="' + siteUrl + '/cookies.html" style="color:#8fa3b8;">Cookies</a> · '
  +     '<a href="' + unsubMail + '" style="color:#8fa3b8;">Cancelar suscripción</a>'
  +   '</p>'
  +   '<p style="margin:10px 0 0 0; font-size:11px; color:#b0bdc9;">© 2026 RC Celta de Vigo. Todos los derechos reservados.</p>'
  + '</td></tr></table></td></tr></table></body></html>';

  const mandrill_payload = {
    key: ($('Vars').first().json.mandrill_api_key),
    message: {
      html,
      subject,
      from_email: fromEmail,
      from_name:  fromName,
      to: [{ email: d.email, type: 'to' }],
      track_opens:  true,
      track_clicks: true,
      metadata: { event_id: String(d.event_id), grada_id: String(d.grada_id) }
    }
  };

  out.push({ json: { ...d, subject, html, mandrill_payload } });
}
return out;
